    def bisection_method(xs, lower_bound, upper_bound, tolerance, max_iterations):
        a, b = lower_bound, upper_bound
        fa, fb = poly(xs, a), poly(xs, b)

        if fa * fb > 0:
            return None

        for _ in range(max_iterations):
            c = (a + b) / 2
            fc = poly(xs, c)

            if abs(fc) < tolerance:
                return c

            if fa * fc < 0:
                b, fb = c, fc
            else:
                a, fa = c, fc

        return (a + b) / 2

    return bisection_method(xs, lower_bound, upper_bound, tolerance, max_iterations)
