def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    # We will use Newton's method to find a root of the polynomial.
    def derivative(xs):
        return [i * xs[i] for i in range(1, len(xs))]

    def poly_derivative(xs, x):
        return sum([coeff * math.pow(x, i) for i, coeff in enumerate(derivative(xs))])

    x = 0  # initial guess
    tolerance = 1e-7
    max_iterations = 1000

    for _ in range(max_iterations):
        y = poly(xs, x)
        if abs(y) < tolerance:
            return x
        y_prime = poly_derivative(xs, x)
        if y_prime == 0:
            break
        x -= y / y_prime

    raise ValueError("Failed to find a zero")
