def find_zero(xs: list):
    def derivative(xs: list):
        return [i * xs[i] for i in range(1, len(xs))]

    def newton_method(xs: list, initial_guess: float = 0.0):
        tolerance = 1e-7
        x = initial_guess
        max_iterations = 1000
        for _ in range(max_iterations):
            y = poly(xs, x)
            if abs(y) < tolerance:
                return x
            y_prime = poly(derivative(xs), x)
            if y_prime == 0:
                raise ValueError("Derivative was zero, can't apply Newton's method")
            x = x - y / y_prime
        raise RuntimeError("Did not converge")

    return newton_method(xs)
